include { GLIMPSE2_CHUNK                          } from 'nf-core/glimpse2/chunk'
include { GLIMPSE2_SPLITREFERENCE                 } from 'nf-core/glimpse2/splitreference'
include { GLIMPSE2_PHASE                          } from 'nf-core/glimpse2/phase'
include { GLIMPSE2_LIGATE                         } from 'nf-core/glimpse2/ligate'
include { BCFTOOLS_INDEX as BCFTOOLS_INDEX_PHASE  } from 'nf-core/bcftools/index'
include { BCFTOOLS_INDEX as BCFTOOLS_INDEX_LIGATE } from 'nf-core/bcftools/index'

workflow BAM_VCF_IMPUTE_GLIMPSE2 {
    take:
    ch_input // channel (mandatory): [ meta, vcf, csi, list, infos ]
    ch_ref // channel (mandatory): [ meta, vcf, csi, region ]
    ch_chunks // channel (optional) : [ meta, regionin, regionout ]
    ch_map // channel (optional) : [ meta, map ]
    ch_fasta // channel (optional) : [ meta, fasta, index ]
    chunk // val (optional): boolean to activate/deactivate chunking step
    chunk_model // val (optional): model file for chunking
    splitreference // val (optional): boolean to activate/deactivate split reference step

    main:

    if (chunk == true) {
        // Error if pre-defined chunks are provided when chunking is activated
        ch_chunks
            .filter { _meta, regionin, regionout -> regionin.size() > 0 || regionout.size() > 0 }
            .subscribe {
                error("ERROR: Cannot provide pre-defined chunks (regionin) when chunk=true. Please either set chunk=false to use provided chunks, or remove input chunks to enable automatic chunking.")
            }

        // Chunk reference panel
        ch_ref_map = ch_ref.combine(ch_map, by: 0)
        GLIMPSE2_CHUNK(ch_ref_map, chunk_model)

        ch_chunks = GLIMPSE2_CHUNK.out.chunk_chr
            .splitCsv(
                header: [
                    'ID',
                    'Chr',
                    'RegionBuf',
                    'RegionCnk',
                    'WindowCm',
                    'WindowMb',
                    'NbTotVariants',
                    'NbComVariants',
                ],
                sep: "\t",
                skip: 0,
            )
            .map { meta, it -> [meta, it["RegionBuf"], it["RegionCnk"]] }
    }

    ch_chunks
        .filter { _meta, regionin, regionout -> regionin.size() > 0 && regionout.size() > 0 }
        .ifEmpty { error("ERROR: ch_chunks channel is empty. Please provide a valid channel or set chunk parameter to true.") }

    ch_chunks_counts = ch_chunks
        .groupTuple()
        .map { metaPC, _regionins, regionouts ->
            [metaPC, regionouts.size()]
        }

    split_input = ch_ref
        .combine(ch_chunks, by: 0)
        .combine(ch_chunks_counts, by: 0)
        .combine(ch_map, by: 0)
        .map { meta, ref, ref_index, _region, regionin, regionout, region_size, gmap ->
            def chr = regionout.tokenize(':')[0]
            def region = regionout.tokenize(':')[1]
            def start = region.tokenize('-')[0]
            def end = region.tokenize('-')[1]
            def paddedStart = String.format('%010d', start as long)
            def paddedEnd = String.format('%010d', end as long)
            def regionoutPadded = "${chr}:${paddedStart}-${paddedEnd}"
            [
                meta + ["regionout": regionout, "regionoutPadded": regionoutPadded, "regionSize": region_size],
                ref,
                ref_index,
                regionin,
                regionout,
                gmap,
            ]
        }

    if (splitreference == true) {
        // Split reference panel in bin files
        GLIMPSE2_SPLITREFERENCE(split_input)

        // Everything is provided by the bin file so no additional file
        ch_chunks_panel_map = GLIMPSE2_SPLITREFERENCE.out.bin_ref
            .map { meta, bin_ref -> [
                meta,
                [], [],
                bin_ref, [],
                []
            ] }
    } else {
        ch_chunks_panel_map = split_input
            .map { meta, ref, ref_index, regionin, regionout, gmap ->
                [
                    meta,
                    regionin, regionout,
                    ref, ref_index,
                    gmap,
                ]
            }
    }

    ch_chunks_panel_map.ifEmpty {
        error("ERROR: join operation resulted in an empty channel. Please provide a valid ch_chunks and ch_map channel as input.")
    }

    ch_phase_input = ch_input
        .combine(ch_chunks_panel_map)
        .map { metaI, input, input_index, list, infos, metaCPM, regionin, regionout, panel, panel_index, gmap ->
            [
                metaI + metaCPM,
                input, input_index,
                list, infos,
                regionin, regionout,
                panel, panel_index,
                gmap,
            ]
        }

    // Impute with Glimpse2
    GLIMPSE2_PHASE(ch_phase_input, ch_fasta, "bcf")

    // Index phased file
    BCFTOOLS_INDEX_PHASE(GLIMPSE2_PHASE.out.phased_variants)

    // Ligate all phased files in one and index it
    ligate_input = GLIMPSE2_PHASE.out.phased_variants
        .join(
            BCFTOOLS_INDEX_PHASE.out.index,
            failOnMismatch: true,
            failOnDuplicate: true,
        )
        .map { meta, vcf, index ->
            def keysToKeep = meta.keySet() - ['regionout', 'regionoutPadded', 'regionSize']
            [
                groupKey(meta.subMap(keysToKeep), meta.regionSize),
                vcf, index,
            ]
        }
        .groupTuple()
        .map { groupKeyObj, vcf, index ->
            // Extract the actual meta from the groupKey
            def meta = groupKeyObj.getGroupTarget()
            [meta, vcf, index]
        }
        .branch { meta, vcf, index ->
            one: vcf.size() == 1
                return [meta, vcf.get(0), index.get(0)]
            more: vcf.size() > 1
                return [meta, vcf, index]
        }

    GLIMPSE2_LIGATE(ligate_input.more)

    BCFTOOLS_INDEX_LIGATE(GLIMPSE2_LIGATE.out.merged_variants)

    // Join imputed and index files
    ch_vcf_index = GLIMPSE2_LIGATE.out.merged_variants.join(
        BCFTOOLS_INDEX_LIGATE.out.index,
        failOnMismatch: true,
        failOnDuplicate: true,
    ).mix(
        ligate_input.one
    )

    emit:
    chunks    = ch_chunks // channel: [ val(meta), regionin, regionout ]
    vcf_index = ch_vcf_index // channel: [ val(meta), vcf, index ]
}

nextflow_workflow {

    name "Test Workflow BAM_VCF_IMPUTE_GLIMPSE2"
    config "./nextflow.config"
    script "../main.nf"
    workflow "BAM_VCF_IMPUTE_GLIMPSE2"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "bam_vcf_impute_glimpse2"
    tag "subworkflows/bam_vcf_impute_glimpse2"

    tag "bcftools"
    tag "bcftools/index"
    tag "glimpse2"
    tag "glimpse2/chunk"
    tag "glimpse2/ligate"
    tag "glimpse2/phase"
    tag "glimpse2/splitreference"

    test("homo_sapiens - vcf no list and no sample, panel vcf region, no chunks, no map, no fasta, chunk recursive + splitreference") {
        when {
            workflow {
                """
                input[0] = channel.of([
                    [id:'input_vcf'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz.csi", checkIfExists: true),
                    [], []
                ]) // input
                input[1] = channel.of([
                    [panel:'ref_panel', chr: "22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true),
                    "chr22"
                ]) // reference
                input[2] = channel.of([
                    [panel: 'ref_panel', chr: "22"],
                    [], []
                ]) // chunks
                input[3] = channel.of([
                    [panel: 'ref_panel', chr: "22"],
                    []
                ]) // map
                input[4] = channel.of([
                    [id_genome:'ref_fasta'], [], []
                ]).collect() // genome
                input[5] = true // perform chunking
                input[6] = "recursive" // chunking model
                input[7] = true // splitreference
                """
            }
        }
        then {
            assert workflow.success
            assert snapshot(
                workflow.out.chunks,
                workflow.out.vcf_index.collect{[
                    it[0],
                    path(it[1]).getFileName().toString(),
                    path(it[2]).getFileName().toString(),
                    path(it[1]).vcf.summary,
                    path(it[1]).vcf.header.getGenotypeSamples().sort(),
                    path(it[1]).vcf.variantsMD5
                ]}
            ).match()
        }
    }
    test("homo_sapiens - vcf no list with sample, panel vcf region, chunks, map, no fasta, no chunking + splitreference") {
        when {
            workflow {
                """
                sample = channel.of('NA12878 2')
                    .collectFile(name: 'sampleinfos.txt')
                input[0] = channel.of([
                    [id:'input_vcf'],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz", checkIfExists: true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr22.1X.vcf.gz.csi", checkIfExists: true),
                    [] // no list
                ])
                .combine(sample)
                input[1] = channel.of([
                    [panel: 'ref_panel', chr: "22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true),
                    "chr22:16570065-16609999",
                ])
                input[2] = channel.of(
                    [[panel: 'ref_panel', chr: "22"], "chr22:16570065-16597215", "chr22:16570065-16592216"],
                    [[panel: 'ref_panel', chr: "22"], "chr22:16587172-16609999", "chr22:16592229-16609999"]
                ) // chunks
                input[3] = channel.of([
                    [panel: 'ref_panel', chr: "22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.glimpse.map", checkIfExists: true)
                ]) // map
                input[4] = channel.of([
                    [id_genome:'ref_fasta'], [], []
                ]).collect() // genome
                input[5] = false // do not perform chunking
                input[6] = "recursive" // chunking model
                input[7] = true // splitreference
                """
            }
        }
        then {
            assert workflow.success
            assert snapshot(
                workflow.out.chunks,
                workflow.out.vcf_index.collect{[
                    it[0],
                    path(it[1]).getFileName().toString(),
                    path(it[2]).getFileName().toString(),
                    path(it[1]).vcf.summary,
                    path(it[1]).vcf.header.getGenotypeSamples().sort(),
                    path(it[1]).vcf.variantsMD5
                ]}
            ).match()
        }
    }
    test("homo_sapiens - vcf no list with sample, panel vcf region, chunks, map, no fasta, no chunking + no splitreference") {
        when {
